  player.shootCooldown=Math.max(0,player.shootCooldown-dt);player.invuln=Math.max(0,player.invuln-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').style.opacity=0}if(hitTimer>0){hitTimer-=dt;if(hitTimer<=0)document.getElementById('hitmarker').style.opacity=0}
