   if(dist>2.5){p.x+=dx/dist*e.speed*dt;p.z+=dz/dist*e.speed*dt}else if(Math.random()<dt*1.1)damagePlayer(8);
   e.attack-=dt;if(e.attack<=0&&dist<24){enemyFire(e);e.attack=1.8+Math.random()*1.6}
  }
