 } else {if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').style.opacity=0}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.mesh.position.addScaledVector(p.vel,dt);p.life-=dt;if(p.mesh.position.distanceTo(camera.position)<.65){damagePlayer(12);p.life=0}if(p.life<=0){scene.remove(p.mesh);projectiles.splice(i,1)}}
